param()

$gitDir      = ".git"
$hooksDir    = Join-Path $gitDir "hooks"
$targetHook  = Join-Path $hooksDir "post-checkout"
$projectHook = ".seg/Scripts/Git/Hooks/PostCheckout.ps1"

if (-not (Test-Path $gitDir)) { return }

if (Test-Path $projectHook) {
    if (-not (Test-Path $hooksDir)) {
        New-Item -ItemType Directory -Path $hooksDir -Force | Out-Null
    }

    $dispatcher = @'
#!/bin/sh
# Auto-generated by GitHookInit.ps1

if [ -f ".seg/Scripts/Git/Hooks/PostCheckout.ps1" ]; then
  pwsh -NoProfile -ExecutionPolicy Bypass -File ".seg/Scripts/Git/Hooks/PostCheckout.ps1" "$@"
fi
'@

    $dispatcher | Set-Content -Path $targetHook -Encoding UTF8

    try { git update-index --chmod=+x ".git/hooks/post-checkout" 2>$null } catch {}
    Write-Host "[INIT] Running post-checkout hook..." -ForegroundColor Cyan
    if((-not $env:WorkflowRunningEnvironment) -or( $env:WorkflowRunningEnvironment -ne 'Jenkins')){
        pwsh -NoProfile -ExecutionPolicy Bypass -File $projectHook
    }
    
}
else {
    if (Test-Path $targetHook) {
        Remove-Item $targetHook -Force
    }
}
